import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Tre numeri dominano i moduli di caricamento delle immagini: 50 KB, 100 KB e 200 KB. Sembrano simili, ma le foto che producono non lo sono.</p>\n<p>Scegli quello sbagliato e o il caricamento fallisce o butti via qualità senza motivo. Scegli quello giusto e il modulo accetta il file al primo tentativo.</p>\n<p>Questo confronto mostra cosa fa ogni dimensione a una foto, dove appartiene ciascuna e come decidere in meno di un minuto.</p>\n<h2 id=\"the-short-answer\">La risposta breve</h2>\n<p>Usa la dimensione maggiore che il portale consente. Un’immagine da 200 KB sembra quasi sempre meglio di una da 100 KB, e 100 KB batte 50 KB.</p>\n<p>Stringi a 50 KB solo quando un modulo lo richiede. Non c’è nessuna ricompensa per andare più in basso del limite.</p>\n<p>Pensa al limite come a un tetto, non a un obiettivo. Il tuo compito è restare sotto di esso conservando quanta più qualità possibile.</p>\n<p>Quando non viene indicato nessun limite, 200 KB sono l’impostazione sensata per le foto sul web. Bilanciano bene nitidezza e velocità.</p>\n<h2 id=\"what-50kb-looks-like\">Come si presenta un’immagine da 50 KB</h2>\n<p>A 50 KB un ritratto resta riconoscibile e utilizzabile. Il volto è chiaro, il contorno è pulito e l’immagine fa il suo lavoro.</p>\n<p>Guardando più da vicino, il compromesso si vede. I capelli perdono le singole ciocche, i tessuti perdono la trama e gli sfondi lisci possono mostrare lievi bande di colore.</p>\n<p>Il testo è il punto debole. Le lettere piccole di un documento scansionato possono ammorbidirsi fino ad affaticare gli occhi, anche se il testo grande resta leggibile.</p>\n<p>Per i lavori a cui è destinata, 50 KB bastano. I portali per passaporti e gli enti d’esame sono stati progettati intorno a questa misura, e chi esamina se l’aspetta.</p>\n<h2 id=\"what-100kb-looks-like\">Come si presenta un’immagine da 100 KB</h2>\n<p>Raddoppiare il budget a 100 KB porta un miglioramento visibile. I bordi si fanno più nitidi, la pelle sembra più naturale e gli sfondi si ammorbidiscono.</p>\n<p>Una foto tessera a 100 KB si vede bene a dimensioni normali. La maggior parte delle persone non noterebbe nemmeno che è stata compressa.</p>\n<p>Anche gli screenshot migliorano nettamente. Il testo dell’interfaccia resta nitido e le piccole etichette che a 50 KB si sfocavano tornano leggibili.</p>\n<p>Per questo 100 KB sono il punto di equilibrio ideale per curriculum e portali di lavoro. Sono abbastanza piccoli per qualsiasi sistema e abbastanza grandi da sembrare professionali.</p>\n<h2 id=\"what-200kb-looks-like\">Come si presenta un’immagine da 200 KB</h2>\n<p>A 200 KB una tipica foto per il web sembra quasi identica all’originale. Solo un confronto pixel per pixel rivela la compressione.</p>\n<p>Le foto di prodotto ne beneficiano di più. La texture dei tessuti, la lucentezza dei gioielli e le etichette stampate sopravvivono tutte a questa dimensione.</p>\n<p>Anche infografiche e grafici stanno qui. Le linee sottili e le piccole annotazioni hanno bisogno dei dati in più per restare nitide.</p>\n<p>Blog e negozi online scelgono i 200 KB proprio per questo. Le pagine restano veloci mentre le immagini restano convincenti.</p>\n<h2 id=\"side-by-side\">Fianco a fianco: la stessa foto a tre dimensioni</h2>\n<p>Immagina un ritratto scattato con il telefono. A 200 KB i capelli hanno le singole ciocche e la camicia mostra la sua trama.</p>\n<p>A 100 KB le ciocche si fondono leggermente e la trama si ammorbidisce. Il volto, però, sembra lo stesso, ed è quello che conta di più.</p>\n<p>A 50 KB i capelli diventano una massa liscia e lo sfondo può presentare bande. Il volto è ancora chiaro, ma la foto sembra più piatta.</p>\n<p>Ora immagina invece uno screenshot. Il divario si allarga: un testo nitido a 200 KB può essere appena leggibile a 100 KB e sfocato a 50 KB.</p>\n<h2 id=\"file-size-and-dimensions\">Il peso del file non è tutta la storia</h2>\n<p>Le dimensioni contano quanto il peso del file. Un’immagine da 50 KB a 600 per 600 pixel si vede molto meglio di un’immagine da 50 KB a 2000 per 2000 pixel.</p>\n<p>Il motivo è la densità. Gli stessi 50 KB distribuiti su meno pixel danno a ogni pixel più dati, così i dettagli sopravvivono meglio.</p>\n<p>Per questo il compressore riduce le dimensioni quando la sola qualità non centra l’obiettivo. Un’immagine più piccola e nitida batte una più grande e pastosa.</p>\n<p>Quando un portale fissa le dimensioni, questa via di fuga si chiude. Allora la scelta del formato diventa la leva principale, e il WebP spesso aiuta.</p>\n<h2 id=\"which-size-for-which-job\">Quale dimensione per quale lavoro?</h2>\n<p>Passaporto, visto e moduli d’esame: 50 KB, perché il portale lo richiede. Usa il <a href=\"/it/comprimi-immagine-a-50kb/\">compressore a 50 KB</a> e rispetta le dimensioni richieste.</p>\n<p>Curriculum, portali di lavoro e foto profilo: 100 KB. Usa il <a href=\"/it/comprimi-immagine-a-100kb/\">compressore a 100 KB</a> per il miglior equilibrio tra qualità e compatibilità.</p>\n<p>Immagini di blog, foto di prodotto e scatti di portfolio: 200 KB. Usa il <a href=\"/it/comprimi-immagine-a-200kb/\">compressore a 200 KB</a> per conservare i dettagli che vendono.</p>\n<p>Per qualsiasi limite personalizzato, usa il <a href=\"/it/comprimi-immagine-a-dimensione-desiderata/\">compressore a dimensione desiderata</a> e digita il numero esatto che chiede il modulo.</p>\n<h2 id=\"format-effects\">Come il formato cambia il confronto</h2>\n<p>Il JPG è il formato più sicuro a tutte e tre le dimensioni. Ogni portale lo accetta e gestisce bene le foto da 50 KB a 200 KB.</p>\n<p>Il WebP di solito vince in qualità per kilobyte. A 50 KB può sembrare visibilmente più pulito del JPG, ma alcuni portali datati lo rifiutano.</p>\n<p>Il PNG ha senso solo per grafiche con colori piatti e bordi netti. Per le foto perde a ogni dimensione, perché non riesce a perdere abbastanza peso.</p>\n<p>La regola pratica è semplice: JPG, a meno che il portale accetti il WebP e ti serva la qualità in più a 50 KB.</p>\n<h2 id=\"loading-speed\">E la velocità di caricamento delle pagine?</h2>\n<p>Su una pagina web, la differenza tra 50 KB e 200 KB è reale ma piccola. Un’immagine principale da 200 KB si carica comunque in fretta su una connessione decente.</p>\n<p>Il rischio maggiore è l’accumulo. Dieci immagini da 200 KB pesano insieme 2 MB, mentre dieci da 50 KB pesano solo 500 KB.</p>\n<p>Per una pagina con molte immagini, 100 KB sono spesso il giusto compromesso. Mantengono il peso totale ragionevole senza danneggiare visibilmente nessuna singola foto.</p>\n<p>Per una sola immagine principale, usa 200 KB. Un unico file grande non rallenterà la pagina, e la differenza di qualità si vede.</p>\n<h2 id=\"decision-framework\">Uno schema di decisione in un minuto</h2>\n<p>Primo, leggi il limite. Se il modulo indica un numero, quel numero decide e la discussione è chiusa.</p>\n<p>Secondo, controlla le regole sul formato. Se il WebP è rifiutato, usa il JPG anche se il WebP sembrerebbe leggermente meglio.</p>\n<p>Terzo, considera il contenuto. Le immagini ricche di testo hanno bisogno di più budget dei ritratti, quindi sali di una dimensione quando il testo conta.</p>\n<p>Quarto, prova il risultato. Comprimi alla dimensione scelta, controlla l’anteprima a dimensione piena e solo allora invia.</p>\n<ul>\n<li>Il portale richiede 50 KB: usa lo strumento a 50 KB, JPG o WebP.</li>\n<li>Curriculum o foto profilo: 100 KB in JPG.</li>\n<li>Blog o foto di prodotto: 200 KB in JPG o WebP.</li>\n<li>Limite personalizzato: digita il numero esatto nello strumento a dimensione desiderata.</li>\n<li>Immagine ricca di testo: sali di una dimensione rispetto a quanto avevi pensato.</li>\n</ul>\n<h2 id=\"when-to-use-100kb-instead\">Quando passare da 50 KB a 100 KB</h2>\n<p>Molti scelgono i 50 KB per impostazione predefinita perché sembrano sicuri. Ma se il modulo consente 100 KB, usare 50 KB butta via solo qualità.</p>\n<p>Un ritratto a 100 KB conserva la texture dei capelli e i dettagli dei vestiti che a 50 KB si perdono. Per un profilo professionale, la differenza si vede.</p>\n<p>Gli screenshot ne beneficiano ancora di più. Il testo piccolo che a 50 KB si sfoca resta leggibile a 100 KB, e questo conta per certificati e moduli.</p>\n<p>La regola è semplice: usa sempre la dimensione maggiore che il modulo consente. Più piccolo non è meglio, a meno che il modulo lo richieda.</p>\n<p>Se il modulo indica 100 KB come tetto, usa il <a href=\"/it/comprimi-immagine-a-100kb/\">compressore a 100 KB</a> e lascia che massimizzi la qualità entro quel budget.</p>\n<h2 id=\"quality-vs-dimensions\">Qualità contro dimensioni: il vero compromesso</h2>\n<p>La compressione ha due leve: qualità e dimensioni. La qualità decide quanti dettagli vengono buttati via per pixel, mentre le dimensioni decidono quanti pixel esistono.</p>\n<p>Abbassare la qualità mantiene l’immagine grande ma morbida. Ridurre le dimensioni la mantiene nitida ma piccola. Il risultato migliore bilancia entrambe.</p>\n<p>Lo strumento prova prima la qualità, perché la maggior parte delle persone vuole mantenere le proprie dimensioni. Solo quando la qualità da sola non basta, scende con la misura.</p>\n<p>Per un ritratto, un piccolo taglio di dimensioni è spesso invisibile. Un volto largo 500 pixel sembra uguale a uno largo 600 quando viene mostrato in piccolo.</p>\n<p>Per il testo, le dimensioni contano di più. Rimpicciolire un documento rende le lettere più piccole, quindi preferisci un taglio di qualità a uno di dimensioni quando il testo deve restare leggibile.</p>\n<h2 id=\"colour-banding\">Il banding di colore e come evitarlo</h2>\n<p>Il banding di colore si presenta come strisce visibili nelle zone lisce, come cieli o pareti neutre. È il difetto visivo più comune alle dimensioni piccole.</p>\n<p>Il banding nasce perché la compressione semplifica le sfumature. Con soli 50 KB a disposizione, un cielo liscio può essere salvato come poche bande piatte.</p>\n<p>I ritratti con sfondo neutro sono i più colpiti. Uno sfondo da studio che dovrebbe essere un unico colore liscio può mostrare anelli.</p>\n<p>Il WebP gestisce le sfumature leggermente meglio del JPG alla stessa dimensione. Se il banding ti dà fastidio, prova prima l’uscita in WebP.</p>\n<p>Anche aggiungere una leggera texture allo sfondo aiuta. Uno sfondo con un lieve rumore dà al compressore qualcosa con cui lavorare.</p>\n<h2 id=\"choosing-between-the-three\">Un modo pratico per scegliere tra le tre dimensioni</h2>\n<p>Inizia leggendo il modulo. Se indica una dimensione, la scelta è fatta e dovresti smettere di decidere e iniziare a comprimere.</p>\n<p>Se il modulo indica un intervallo, scegli il valore più alto. Un limite di 200 KB significa che puoi usare 200 KB, e la tua immagine te ne sarà grata.</p>\n<p>Considera poi il contenuto. Un ritratto regge bene i 50 KB, mentre uno screenshot o un’infografica hanno bisogno di 100 KB o 200 KB.</p>\n<p>Considera anche chi guarderà. Una foto per chi esamina una pratica pubblica deve essere chiara, non bella, quindi 50 KB vanno bene. Una foto di portfolio deve colpire, quindi usa 200 KB.</p>\n<p>Quando due dimensioni funzionano entrambe, confrontale. Comprimi la stessa immagine a 50 KB e a 100 KB, guardale fianco a fianco e lascia decidere i tuoi occhi.</p>\n<h2 id=\"future-proofing\">Proteggere le immagini compresse per il futuro</h2>\n<p>Conserva il file originale per sempre. Un’immagine compressa non può mai tornare alla qualità piena, con nessuno strumento.</p>\n<p>Salva le copie compresse con nomi descrittivi. Un nome che include dimensione e scopo ti risparmia di dover ricomprimere in seguito.</p>\n<p>Non comprimere un file compresso. Ogni passaggio aggiunge danni, e due passaggi a 50 KB sembrano molto peggio di uno solo.</p>\n<p>Se un portale aggiorna le regole, comprimi di nuovo dall’originale. Un file fatto per il tetto di 50 KB dell’anno scorso potrebbe non andare bene per il tetto di 100 KB di quest’anno.</p>\n<p>Tratta l’originale come il master e ogni copia compressa come usa e getta. Questa abitudine protegge le tue foto per anni.</p>\n<h2 id=\"upload-speeds\">Velocità di caricamento e connessioni lente</h2>\n<p>Un file da 50 KB si carica all’istante anche con una connessione debole, mentre un originale da 5 MB può andare in timeout. Quell’affidabilità è parte del motivo per cui i portali richiedono file piccoli.</p>\n<p>Se la tua connessione è lenta, comprimi prima di aprire il modulo. Caricare una foto da 5 MB su un compressore spreca la stessa banda che stai cercando di risparmiare.</p>\n<p>Ricorda che lo strumento elabora i file in locale. Una volta caricata la pagina, la compressione stessa non ha bisogno di alcuna connessione.</p>\n<p>Su una rete condivisa o pubblica, i file piccoli significano anche meno esposizione. Un caricamento da 50 KB finisce prima che qualcuno possa interferire.</p>\n<p>Per chi vive in zone con internet lento, il limite di 50 KB è davvero utile. Mantiene il procedimento veloce per tutti, non solo per chi ha la fibra.</p>\n<h2 id=\"printing-50kb\">Si può stampare un’immagine da 50 KB?</h2>\n<p>Un’immagine da 50 KB si può stampare, ma solo in piccolo. Una stampa formato tessera va bene, mentre una stampa A4 risulterà morbida e pixellata.</p>\n<p>La stampa richiede circa 300 pixel per pollice. Un’immagine larga 600 pixel si stampa in modo pulito a due pollici di larghezza, adatto a foto tessera e piccole stampe.</p>\n<p>Non usare mai un file da 50 KB per stampe più grandi di una piccola. I dettagli mancanti diventano evidenti non appena l’immagine cresce.</p>\n<p>Conserva l’originale per la stampa. La copia da 50 KB esiste per i caricamenti, e l’originale esiste per tutto il resto.</p>\n<p>Se un portale ti chiede di stampare il modulo con la foto, controlla prima l’anteprima di stampa. Una foto che a schermo sembra a posto può risultare ruvida su carta.</p>\n<h2 id=\"accessibility\">Accessibilità: far funzionare le immagini compresse per tutti</h2>\n<p>Un’immagine compressa deve comunque restare comprensibile. Una foto tessera deve mostrare il volto in modo abbastanza chiaro perché chiunque esamini possa identificare la persona.</p>\n<p>Un contrasto alto aiuta. Un volto che spicca sullo sfondo è più facile da vedere per tutti, compresi chi ha una vista debole.</p>\n<p>Evita di affidarti solo al colore. Un modulo che usa il colore per separare le zone diventa confuso quando la compressione smorza i colori.</p>\n<p>Per le immagini web, aggiungi sempre un testo alternativo descrittivo. Un’immagine da 100 KB con un buon testo alternativo serve più persone di un’immagine perfetta senza.</p>\n<p>Compressione e accessibilità vanno insieme. Una fonte chiara e ad alto contrasto si comprime meglio ed è più facile da leggere per ogni spettatore.</p>\n<p>Se sei ancora indeciso, parti da 100 KB. È la dimensione intermedia più tollerante, e puoi salire o scendere dopo aver visto l’anteprima.</p>\n<p>Per la guida completa alla dimensione più piccola, leggi <a href=\"/it/blog/comprimere-immagine-a-50kb-guida/\">Comprimere un’immagine a 50 KB: guida completa</a>. Per i passaggi pratici, vedi <a href=\"/it/blog/come-comprimere-immagine-a-50kb/\">Come comprimere un’immagine a 50 KB</a>. Le guide a 100 KB e 200 KB trattano le dimensioni maggiori con lo stesso dettaglio.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"100 KB è il doppio meglio di 50 KB?","answer":"Non esattamente il doppio, ma il miglioramento si vede facilmente. Un ritratto da 100 KB conserva molti più dettagli di capelli e tessuti, e il testo resta più nitido. Il salto da 100 KB a 200 KB è più piccolo, perché la maggior parte delle foto sembra già pulita a 100 KB."},{"question":"Un portale capisce se la mia immagine è da 51 KB invece di 50 KB?","answer":"Sì. I portali controllano il numero esatto di byte, quindi 51 KB non supera un limite di 50 KB anche se la differenza è minima. I compressori puntano leggermente sotto il limite, di solito intorno a 48–49,9 KB, per lasciare un margine di sicurezza."},{"question":"Quale dimensione uso per una foto profilo di LinkedIn?","answer":"LinkedIn non impone un tetto di 50 KB, quindi 100 KB o 200 KB sono meglio. Una foto tessera da 200 KB è la più nitida, mentre 100 KB bastano per un piccolo ritaglio circolare. Usa 50 KB solo se un modulo specifico lo richiede."},{"question":"Un file più grande significa sempre un’immagine più bella?","answer":"Fino a un certo punto. Passare da 50 KB a 200 KB migliora visibilmente una foto, ma passare da 200 KB a 2 MB aggiunge poco a dimensioni di visualizzazione normali. I dati in più conservano soprattutto dettagli che non si vedono senza ingrandire."},{"question":"Perché il mio screenshot sembra peggio a 50 KB del mio ritratto?","answer":"Gli screenshot contengono bordi netti e testo minuscolo, che sono costosi da salvare. I ritratti hanno zone lisce che si comprimono a poco prezzo. Le immagini ricche di testo hanno bisogno di un budget maggiore, quindi usa 100 KB o 200 KB per gli screenshot quando il modulo lo consente."},{"question":"Se il modulo consente 200 KB, c’è un motivo per usare 50 KB?","answer":"No. Usare una dimensione più piccola di quella consentita butta via solo qualità. Usa sempre la dimensione maggiore che il modulo permette e lascia che il compressore massimizzi la qualità entro quel budget."}];
